SELECT     p.vdate                                               AS \"REPORT DATE\",     wd.HALF_NO                                            AS \"FISCAL HALF\",     wd.MONTH_NO                                           AS \"FISCAL MONTH\",     wd.WEEK_NO                                            AS \"FISCAL WEEK\",     p.CURR_454_WEEK                                       AS \"WEEK START DATE\",     wd.DEPT                                               AS \"DEPTARTMENT\",     d.DEPT_NAME                                           AS \"DEPT NAME\",     wd.CLASS                                              AS \"CLASS NO\",     c.CLASS_NAME                                          AS \"CLASS NAME\",     wd.SUBCLASS                                           AS \"SUBCLASS\",     sc.SUB_NAME                                           AS \"SUBCLASS NAME\",     wd.LOCATION                                           AS \"WAREHOUSE ID\",     wh.WH_NAME                                            AS \"WAREHOUSE NAME\",     ROUND(wd.OPN_STK_COST,2)                              AS \"OPEN STOCK COST\",     ROUND(wd.OPN_STK_RETAIL,2)                            AS \"OPEN STOCK RETAIL\",     ROUND(wd.CLS_STK_COST,2)                              AS \"CLOSE STOCK COST\",     ROUND(wd.CLS_STK_RETAIL,2)                            AS \"CLOSE STOCK RETAIL\",     ROUND(wd.NET_SALES_RETAIL,2)                          AS \"NET SALES RETAIL\",     ROUND(wd.NET_SALES_COST,2)                            AS \"NET SALES COST\",     ROUND(wd.SALES_UNITS,2)                               AS \"SALES UNITS\",     ROUND(wd.TSF_IN_RETAIL,2)                             AS \"TSF IN RETAIL\",     ROUND(wd.TSF_IN_COST,2)                               AS \"TSF IN COST\",     ROUND(wd.TSF_OUT_RETAIL,2)                            AS \"TSF OUT RETAIL\",     ROUND(wd.TSF_OUT_COST,2)                              AS \"TSF OUT COST\",     ROUND(wd.RTV_RETAIL,2)                                AS \"RTV RETAIL\",     ROUND(wd.RTV_COST,2)                                  AS \"RTV COST\",     ROUND(wd.STOCK_ADJ_RETAIL,2)                          AS \"STOCK ADJ RETAIL\",     ROUND(wd.STOCK_ADJ_COST,2)                            AS \"STOCK ADJ COST\",     ROUND(wd.NET_SALES_RETAIL - wd.NET_SALES_COST,2)      AS \"GROSS PROFIT\",     ROUND((wd.NET_SALES_RETAIL - wd.NET_SALES_COST)           / NULLIF(wd.NET_SALES_RETAIL,0) * 100,2)        AS \"GROSS MARGIN PCT\" FROM MFCS_RDS.RDS_WV_WEEK_DATA wd JOIN MFCS_RDS.RDS_WV_PERIOD p     ON wd.HALF_NO  = p.HALF_NO     JOIN MFCS_RDS.RDS_WV_DEPS d     ON wd.DEPT = d.DEPT JOIN MFCS_RDS.RDS_WV_CLASS c     ON wd.DEPT = c.DEPT    AND wd.CLASS = c.CLASS JOIN MFCS_RDS.RDS_WV_SUBCLASS sc     ON wd.DEPT = sc.DEPT    AND wd.CLASS = sc.CLASS    AND wd.SUBCLASS = sc.SUBCLASS JOIN MFCS_RDS.RDS_WV_WH wh     ON wd.LOCATION = wh.WH WHERE wd.LOC_TYPE = 'W' ORDER BY wd.HALF_NO, wd.MONTH_NO, wd.WEEK_NO, d.DEPT_NAME, wh.WH_NAME</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>REPORT DATE</ds:name><ds:datatype>timestamp</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>FISCAL HALF</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>FISCAL MONTH</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>FISCAL WEEK</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>WEEK START DATE</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>DEPTARTMENT</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>DEPT NAME</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>CLASS NO</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:colu